class MajorityChecker { int n;vector<int> candidate,balance;unordered_map<int,vector<int>> positions;pair<int,int> mergePair(int a,int aCount,int b,int bCount){if(a==b)return {a,aCount+bCount};return aCount>=bCount?make_pair(a,aCount-bCount):make_pair(b,bCount-aCount);}void build(int node,int left,int right,vector<int>& arr){if(left==right){candidate[node]=arr[left];balance[node]=1;return;}int middle=(left+right)/2;build(node*2,left,middle,arr);build(node*2+1,middle+1,right,arr);tie(candidate[node],balance[node])=mergePair(candidate[node*2],balance[node*2],candidate[node*2+1],balance[node*2+1]);}pair<int,int> rangeCandidate(int node,int left,int right,int queryLeft,int queryRight){if(queryLeft<=left&&right<=queryRight)return {candidate[node],balance[node]};int middle=(left+right)/2;if(queryRight<=middle)return rangeCandidate(node*2,left,middle,queryLeft,queryRight);if(queryLeft>middle)return rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);auto a=rangeCandidate(node*2,left,middle,queryLeft,queryRight),b=rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);return mergePair(a.first,a.second,b.first,b.second);}public:MajorityChecker(vector<int>& arr):n(arr.size()),candidate(4*n),balance(4*n){for(int i=0;i<n;++i)positions[arr[i]].push_back(i);build(1,0,n-1,arr);}int query(int left,int right,int threshold){int value=rangeCandidate(1,0,n-1,left,right).first;auto& list=positions[value];int count=upper_bound(list.begin(),list.end(),right)-lower_bound(list.begin(),list.end(),left);return count>=threshold?value:-1;} };
